def level_order(root):
    if root is None:
        return []
    result = []
    level = [root]
    while level:
        result.append([node.value for node in level])
        following = []
        for node in level:
            if node.left is not None:
                following.append(node.left)
            if node.right is not None:
                following.append(node.right)
        level = following
    return result

