def level_order(root):
    def depth_of(node):
        if node is None:
            return 0
        return 1 + max(depth_of(node.left), depth_of(node.right))
    def collect(node, remaining, out):
        if node is None:
            return
        if remaining == 0:
            out.append(node.value)
            return
        collect(node.left, remaining - 1, out)
        collect(node.right, remaining - 1, out)
    total = depth_of(root)
    result = []
    for index in range(total):
        level = []
        collect(root, index, level)
        result.append(level)
    return result
